/**
 * Key and password authentication as `buildConnectConfig` assembles it.
 *
 * The handshake integration test only ever uses password auth, and the TOFU
 * test only looks at `hostVerifier`, so the key branch — parse, passphrase
 * lookup, the error strings that cross IPC, the per-file cache — had no
 * main-process coverage at all. Keys here are real (generated by ssh2), so the
 * parse path is the production one. Path confinement is mocked out: it has its
 * own tests in validate.test.ts and would otherwise tie this file to $HOME.
 */
import { mkdtempSync, rmSync, utimesSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { utils } from 'ssh2';
import { afterAll, beforeEach, describe, expect, it, vi } from 'vitest';

const { retrieveCredential, validateKeyPath } = vi.hoisted(() => ({
  retrieveCredential: vi.fn<(connectionId: string) => string | undefined>(),
  validateKeyPath: vi.fn<(path: string, field: string) => Promise<string>>(),
}));

vi.mock('../../../../src/main/lib/logger', () => ({
  default: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));
vi.mock('../../../../src/main/services/database', () => ({
  getSetting: (_k: string, dflt: number) => dflt,
}));
vi.mock('../../../../src/main/services/emit', () => ({ emitToRenderer: vi.fn() }));
vi.mock('../../../../src/main/services/credential-store', () => ({
  retrieveCredential: (id: string) => retrieveCredential(id),
}));
vi.mock('../../../../src/main/services/host-key-store', () => ({
  verifyHostKey: () => ({ trusted: true }),
  getStoredHostKey: () => null,
  fingerprintKey: () => 'SHA256:test',
}));
vi.mock('../../../../src/main/lib/validate', () => ({
  expandAndValidatePrivateKeyPath: (path: string, field: string) => validateKeyPath(path, field),
}));

import { PendingHostKeyRegistry } from '../../../../src/main/services/ssh/host-key-flow';
import {
  buildConnectConfig,
  type ConnectParams,
} from '../../../../src/main/services/ssh/ssh-config';

const dir = mkdtempSync(join(tmpdir(), 'luna-keyauth-'));
afterAll(() => rmSync(dir, { recursive: true, force: true }));

function writeKey(name: string, passphrase?: string): string {
  const pair = passphrase
    ? utils.generateKeyPairSync('ed25519', { passphrase, cipher: 'aes256-ctr', rounds: 1 })
    : utils.generateKeyPairSync('ed25519');
  const path = join(dir, name);
  writeFileSync(path, pair.private, { mode: 0o600 });
  return path;
}

const plainKey = writeKey('id_plain');
const encryptedKey = writeKey('id_encrypted', 'correct horse');

const base: ConnectParams = { host: 'example.com', port: 22, username: 'alice', authType: 'key' };

function build(params: Partial<ConnectParams>, connectionId?: string) {
  return buildConnectConfig(
    { ...base, ...params },
    { pendingHostKeys: new PendingHostKeyRegistry(), connectionId },
  );
}

beforeEach(() => {
  retrieveCredential.mockReset();
  validateKeyPath.mockReset();
  validateKeyPath.mockImplementation(async (path) => path);
});

describe('key authentication', () => {
  it('loads an unencrypted key as PEM and sends no password', async () => {
    const { config, error } = await build({ privateKeyPath: plainKey });
    expect(error).toBeUndefined();
    expect(String(config.privateKey)).toContain('PRIVATE KEY');
    expect(config.password).toBeUndefined();
    // Key auth must not go looking for a stored password.
    expect(retrieveCredential).not.toHaveBeenCalled();
  });

  it('confines the key path before reading it', async () => {
    await build({ privateKeyPath: '~/.ssh/id_plain' });
    expect(validateKeyPath).toHaveBeenCalledWith('~/.ssh/id_plain', 'privateKeyPath');
  });

  it('decrypts an encrypted key with the passphrase stored for the connection', async () => {
    retrieveCredential.mockReturnValue('correct horse');
    const { config, error } = await build(
      { authType: 'key+passphrase', privateKeyPath: encryptedKey },
      'conn-1',
    );
    expect(error).toBeUndefined();
    expect(retrieveCredential).toHaveBeenCalledWith('conn-1');
    expect(String(config.privateKey)).toContain('PRIVATE KEY');
  });

  it('prefers a transient passphrase (test connection) over the stored one', async () => {
    retrieveCredential.mockReturnValue('stale');
    const { error } = await build(
      { authType: 'key+passphrase', privateKeyPath: encryptedKey, passphrase: 'correct horse' },
      'conn-1',
    );
    expect(error).toBeUndefined();
    expect(retrieveCredential).not.toHaveBeenCalled();
  });

  it('reports a wrong passphrase as an invalid key, without a config key', async () => {
    const { config, error } = await build({
      authType: 'key+passphrase',
      privateKeyPath: encryptedKey,
      passphrase: 'wrong',
    });
    expect(error).toMatch(/^Invalid private key/);
    expect(config.privateKey).toBeUndefined();
  });

  it('refuses an encrypted key in plain key mode', async () => {
    const { error } = await build({ privateKeyPath: encryptedKey });
    expect(error).toMatch(/^Invalid private key/);
  });

  it('asks for a key path when none is configured', async () => {
    const { error } = await build({ privateKeyPath: null });
    expect(error).toBe('Private key path not configured');
  });

  it('reports a missing key file without leaking its path across IPC', async () => {
    const missing = join(dir, 'does-not-exist');
    const { error } = await build({ privateKeyPath: missing });
    expect(error).toBe('Private key file not found');
    expect(error).not.toContain(dir);
  });

  it('explains a key path rejected by home-directory confinement', async () => {
    validateKeyPath.mockRejectedValue(
      new Error('privateKeyPath must be inside the home directory'),
    );
    const { error } = await build({ privateKeyPath: '/etc/ssh/ssh_host_ed25519_key' });
    expect(error).toBe('Private key path must be inside the home directory');
  });

  it('picks up a key file that changed on disk instead of serving the cached one', async () => {
    const path = writeKey('id_rotating');
    const first = await build({ privateKeyPath: path });

    const replacement = utils.generateKeyPairSync('ed25519');
    writeFileSync(path, replacement.private, { mode: 0o600 });
    // Force a different mtime: the cache key is path + mtime + size, and two
    // ed25519 keys are the same size.
    const later = new Date(Date.now() + 5_000);
    utimesSync(path, later, later);
    const second = await build({ privateKeyPath: path });

    expect(second.error).toBeUndefined();
    expect(second.config.privateKey).not.toEqual(first.config.privateKey);
  });
});

describe('password authentication', () => {
  it('uses the stored password for the connection', async () => {
    retrieveCredential.mockReturnValue('hunter2');
    const { config, error } = await build({ authType: 'password' }, 'conn-2');
    expect(error).toBeUndefined();
    expect(config.password).toBe('hunter2');
    expect(config.privateKey).toBeUndefined();
  });

  it('rejects an oversized secret before it reaches ssh2', async () => {
    const { config, error } = await build({ authType: 'password', password: 'x'.repeat(4097) });
    expect(error).toMatch(/exceeds 4096-byte limit/);
    expect(config.password).toBeUndefined();
  });

  it('measures the secret cap in bytes, not characters', async () => {
    // 1366 three-byte characters = 4098 bytes, under 4096 characters.
    const { error } = await build({ authType: 'password', password: '€'.repeat(1366) });
    expect(error).toMatch(/exceeds 4096-byte limit/);
  });
});

describe('negotiated algorithms', () => {
  it('offers only modern ciphers and never SHA-1 RSA host-key signatures', async () => {
    const { config } = await build({ authType: 'password', password: 'pw' });
    const ciphers = (config.algorithms?.cipher ?? []) as string[];
    expect(ciphers.length).toBeGreaterThan(0);
    for (const cipher of ciphers) {
      expect(cipher).toMatch(/gcm|ctr|chacha20/);
    }
    expect(config.algorithms?.serverHostKey).not.toContain('ssh-rsa');
    expect(config.algorithms?.hmac).not.toContain('hmac-sha1');
  });
});
